import{_ as r,I as o,o as i,c as s,j as a,a as n,J as l,ac as d}from"./chunks/framework.iusZwn-q.js";const b=JSON.parse('{"title":"Why Tolki JS?","description":"","frontmatter":{},"headers":[],"relativePath":"why-tolki-js.md","filePath":"why-tolki-js.md","lastUpdated":1771086999000}'),h={name:"why-tolki-js.md"};function p(c,e,u,y,f,v){const t=o("CopyOrDownloadAsMarkdownButtons");return i(),s("div",null,[e[0]||(e[0]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true","data-nosnippet":""},"Are you an LLM? You can read better optimized documentation at /why-tolki-js.md for this page in Markdown format",-1)),e[1]||(e[1]=a("h1",{id:"why-tolki-js",tabindex:"-1"},[n("Why Tolki JS? "),a("a",{class:"header-anchor",href:"#why-tolki-js","aria-label":"Permalink to “Why Tolki JS?”"},"​")],-1)),l(t),e[2]||(e[2]=d('<h2 id="reasoning-for-porting-laravel-php-utilities-to-javascript" tabindex="-1">Reasoning for Porting Laravel PHP Utilities to JavaScript? <a class="header-anchor" href="#reasoning-for-porting-laravel-php-utilities-to-javascript" aria-label="Permalink to “Reasoning for Porting Laravel PHP Utilities to JavaScript?”">​</a></h2><p>I love <a href="https://laravel.com/" target="_blank" rel="noreferrer">Laravel</a>. I love JavaScript <a href="https://vuejs.org/" target="_blank" rel="noreferrer">frontend frameworks</a>. <a href="https://inertiajs.com/" target="_blank" rel="noreferrer">Inertia</a> bridged the gap between these two worlds. I just wish I could use the incredible helper functions that Laravel provides in my JavaScript code.</p><p>That&#39;s why I created Tolki JS Utilities - to bring the power of Laravel&#39;s helper functions to your JavaScript codebase. With these utilities, you can use the same utilities between your backend and frontend code.</p><h2 id="aren-t-there-already-similar-packages" tabindex="-1">Aren&#39;t There Already Similar Packages? <a class="header-anchor" href="#aren-t-there-already-similar-packages" aria-label="Permalink to “Aren&#39;t There Already Similar Packages?”">​</a></h2><p>Yes, there are a few packages that provide string and collection utilities for JavaScript. However, most of these packages are either incomplete, not recently maintained, do not support TypeScript, or are not <a href="https://developer.mozilla.org/en-US/docs/Glossary/Tree_shaking" target="_blank" rel="noreferrer">tree-shakeable</a> in an efficient way.</p><p>It&#39;s about time us Laravel devs with a love for the JavaScript ecosystem have sturdy frontend utility helpers that behave the same way as their backend counterparts.</p><h2 id="what-about-lodash" tabindex="-1">What about Lodash? <a class="header-anchor" href="#what-about-lodash" aria-label="Permalink to “What about Lodash?”">​</a></h2><p>Lodash is great! I&#39;ve used it myself in many projects. However, many of the functions do not behave the same way as their Laravel counterparts. For example, the lodash <code>get</code> function returns <code>undefined</code> if the value is not found, whereas Laravel&#39;s <code>Arr.get</code> function allows you to specify a default value and returns <code>null</code> if the value is not found and no default is provided.</p><p>In order to have a consistent experience between your backend and frontend code, I wanted to create a package that behaves as closely as possible to Laravel&#39;s helper functions. This way, whether you do <code>Arr.get()</code> in PHP or <code>get()</code> in JavaScript, you can expect the same behavior.</p><h2 id="typescript-support" tabindex="-1">TypeScript Support <a class="header-anchor" href="#typescript-support" aria-label="Permalink to “TypeScript Support”">​</a></h2><p>I am big fan of TypeScript, so I wanted to make sure that these utilities have first-class TypeScript support. The entire codebase is written in TypeScript, and type definitions are included for all functions.</p><p>On top of the data utilities, there are some TypeScript types available so that you don&#39;t have to type them in your project. These types include pagination, models, and HTTP resource responses. The goal is to make it as easy as possible to work with Laravel-style data structures in your TypeScript code.</p><h2 id="do-i-have-to-use-laravel-to-use-these-utilities" tabindex="-1">Do I have to use Laravel to use these utilities? <a class="header-anchor" href="#do-i-have-to-use-laravel-to-use-these-utilities" aria-label="Permalink to “Do I have to use Laravel to use these utilities?”">​</a></h2><p>No!</p><p>These utilities are designed to be used in any JavaScript or TypeScript project, regardless of whether you&#39;re using Laravel on the backend. You can use them in React, Vue, Angular, or any other frontend framework or library. You can even use them in plain JavaScript projects that never touch a backend.</p><p>Another option is to use them in your Node.js backend projects if you want to have a consistent experience between your backend and frontend code. (Though I personally hate using JavaScript on the backend)</p>',16))])}const k=r(h,[["render",p]]);export{b as __pageData,k as default};
